func SetData(resource plugin.Resource, field string, val *llx.RawData) error {
	f, ok := setDataFields[resource.MqlName()+"."+field]
	if !ok {
		return errors.New("[netlify] cannot set '" + field + "' in resource '" + resource.MqlName() + "', field not found")
	}

	if ok := f(resource, val); !ok {
		return errors.New("[netlify] cannot set '" + field + "' in resource '" + resource.MqlName() + "', type does not match")
	}
	return nil
}

func SetAllData(resource plugin.Resource, args map[string]*llx.RawData) error {
	var err error
	for k, v := range args {
		if err = SetData(resource, k, v); err != nil {
			return err
		}
	}
	return nil
}

// mqlNetlify for the netlify resource
type mqlNetlify struct {
	MqlRuntime *plugin.Runtime
	__id       string
	// optional: if you define mqlNetlifyInternal it will be used here
	Accounts    plugin.TValue[[]any]
	Sites       plugin.TValue[[]any]
	DnsZones    plugin.TValue[[]any]
	DeployKeys  plugin.TValue[[]any]
	CurrentUser plugin.TValue[*mqlNetlifyUser]
}

// createNetlify creates a new instance of this resource
func createNetlify(runtime *plugin.Runtime, args map[string]*llx.RawData) (plugin.Resource, error) {
	res := &mqlNetlify{
		MqlRuntime: runtime,
	}

	err := SetAllData(res, args)
	if err != nil {
		return res, err
	}

	if res.__id == "" {
		res.__id, err = res.id()
		if err != nil {
			return nil, err
		}
	}

	if runtime.HasRecording {
		args, err = runtime.ResourceFromRecording("netlify", res.__id)
		if err != nil || args == nil {
			return res, err
		}
		return res, SetAllData(res, args)
	}

	return res, nil
}

func (c *mqlNetlify) MqlName() string {
	return "netlify"
}

func (c *mqlNetlify) MqlID() string {
	return c.__id
}

func (c *mqlNetlify) GetAccounts() *plugin.TValue[[]any] {
	return plugin.GetOrCompute[[]any](&c.Accounts, func() ([]any, error) {
		if c.MqlRuntime.HasRecording {
			d, err := c.MqlRuntime.FieldResourceFromRecording("netlify", c.__id, "accounts")
			if err != nil {
				return nil, err
			}
			if d != nil {
				return d.Value.([]any), nil
			}
		}

		return c.accounts()
	})
}

